import type { WalletName } from '@solana/wallet-adapter-base';
import { useWallet } from '@solana/wallet-adapter-react';
import type { ReactElement } from 'react';
import React, { useEffect } from 'react';

export function TipLinkWalletAutoConnectV2({
    children,
    isReady,
    query,
}: {
    children: React.ReactNode;
    isReady: boolean;
    query: {
        tipLinkAutoConnect?: string;
        promptTipLinkAutoConnect?: string;
        get?: (key: string) => string | null;
    };
}): ReactElement {
    const { select } = useWallet();

    useEffect(() => {
        if (!isReady) {
            return;
        }
        if (
            query.tipLinkAutoConnect ||
            query.get?.('tipLinkAutoConnect') ||
            query.promptTipLinkAutoConnect ||
            query.get?.('promptTipLinkAutoConnect')
        ) {
            select('Google via TipLink' as WalletName);
        }
    }, [isReady, query]);

    return <>{children}</>;
}
