import type { TIPLINK_BUILD_ENV_TYPE } from "./interfaces.js";

export const getTipLinkUrl = (buildEnv: TIPLINK_BUILD_ENV_TYPE): string => {
  switch (buildEnv) {
    case "production":
      return "https://tiplink.io";
    case "staging":
      return "https://staging.tiplink.io";
    case "development":
      return "https://dev.tiplink.io";
    case "adapter":
      return "https://adapter.tiplink.io";
    case "local":
      return "http://localhost:3000";
  }
};

export function getCloseButtonUrl(buildEnv: TIPLINK_BUILD_ENV_TYPE): string {
  const logoUrl = new URL(
    "adapter-popup-close-icon.svg",
    getTipLinkUrl(buildEnv)
  );
  return logoUrl.toString();
}
