const edgetOffset = 20;

function preventDefaultScroll(event: TouchEvent) {
  event.preventDefault();
}

function bottom() {
  return window.innerHeight;
}

function right() {
  return window.innerWidth;
}

function getMetadata(widget: HTMLDivElement, x: number, y: number) {
  const vw = right();
  const vh = bottom();
  const isOnLeftSide = x < (vw - edgetOffset) / 2;
  const isCollapsedUi = widget.classList.contains("tipLinkWidget_collapsed");
  const widgetWidth = isCollapsedUi ? 20 : vw > 476 ? 101 : 77;
  const widgetHeight = isCollapsedUi ? 20 : vw > 476 ? 72 : 54;
  const offset = isOnLeftSide
    ? isCollapsedUi
      ? 0
      : 20
    : isCollapsedUi
    ? widgetWidth
    : widgetWidth + 20;
  return {
    vw,
    vh,
    isOnLeftSide,
    isCollapsedUi,
    widgetWidth,
    widgetHeight,
    offset,
  };
}

function stickToNearestCorner(
  x: number,
  y: number,
  widget: HTMLDivElement
): { x: number; y: number } {
  const vw = right();
  const vh = bottom();
  const isOnLeftSide = x < (vw - edgetOffset) / 2;
  const isCollapsedUi = widget.classList.contains("tipLinkWidget_collapsed");
  const widgetWidth = isCollapsedUi ? 20 : vw > 476 ? 101 : 77;
  const widgetHeight = isCollapsedUi ? 54 : vw > 476 ? 72 : 54;
  const offset = isOnLeftSide
    ? isCollapsedUi
      ? 0
      : 20
    : isCollapsedUi
    ? widgetWidth
    : widgetWidth + 20;
  const stickyX = x < (vw - edgetOffset) / 2 ? offset : vw - offset;
  const stickyY =
    y < (vh - edgetOffset) / 2 ? edgetOffset : vh - widgetHeight - edgetOffset;
  return {
    x: stickyX,
    y: stickyY,
  };
}

function stickToNearestSideEdge(
  x: number,
  y: number,
  widget: HTMLDivElement
): { x: number; y: number } {
  const vw = right();
  const vh = bottom();
  const isOnLeftSide = x < (vw - edgetOffset) / 2;
  const isCollapsedUi = widget.classList.contains("tipLinkWidget_collapsed");
  const widgetWidth = isCollapsedUi ? 20 : vw > 476 ? 101 : 77;
  const widgetHeight = isCollapsedUi ? 54 : vw > 476 ? 72 : 54;
  const offset = isOnLeftSide
    ? isCollapsedUi
      ? 0
      : 20
    : isCollapsedUi
    ? widgetWidth
    : widgetWidth + 20;
  const nearestSideX = x < (vw - edgetOffset) / 2 ? offset : vw - offset;
  const boundaryY =
    y < (vh - edgetOffset) / 2
      ? Math.max(edgetOffset, y)
      : Math.min(vh - widgetHeight - edgetOffset, y);
  return {
    x: nearestSideX,
    y: boundaryY,
  };
}

function showExpandedWalletWidget(
  widgetElement: HTMLDivElement,
  theme?: string
) {
  const widgetLogo = document?.getElementById("tiplink-widget-logo");
  const widgetLabel = document?.getElementById("tiplink-widget-text");
  const widgetChevron = document?.getElementById("tiplink-widget-chevron");
  const widgetNotif = document?.getElementById("tiplink-widget-notif");
  if (widgetLogo) {
    widgetLogo.style.display = "block";
  }
  if (widgetLabel) {
    widgetLabel.style.display = "block";
  }
  if (widgetChevron) {
    widgetChevron.style.display = "none";
  }
  if (
    widgetNotif &&
    widgetNotif.classList.contains("tiplinkWidget_notif_show")
  ) {
    widgetNotif.style.removeProperty("left");
    widgetNotif.style.setProperty("right", "-4px");
  }

  updateWalletWidgetClassNames(widgetElement, theme, false);
}

function showCollapsedWalletWidget(
  widgetElement: HTMLDivElement,
  theme?: string,
  isOnLeftSide?: boolean
) {
  // don't collapse on desktop dimension right-side
  const vw = right();
  if (vw > 476 && !isOnLeftSide) return;
  const widgetLogo = document?.getElementById("tiplink-widget-logo");
  const widgetLabel = document?.getElementById("tiplink-widget-text");
  const widgetChevron = document?.getElementById("tiplink-widget-chevron");
  const widgetNotif = document?.getElementById("tiplink-widget-notif");
  if (widgetLogo) {
    widgetLogo.style.display = "none";
  }
  if (widgetLabel) {
    widgetLabel.style.display = "none";
  }
  if (widgetChevron) {
    widgetChevron.style.display = "block";
    widgetChevron.style.transform = isOnLeftSide
      ? "rotate(0)"
      : "rotate(180deg)";
  }
  if (
    widgetNotif &&
    widgetNotif.classList.contains("tiplinkWidget_notif_show") &&
    !isOnLeftSide
  ) {
    widgetNotif.style.removeProperty("right");
    widgetNotif.style.setProperty("left", "-4px");
  }

  updateWalletWidgetClassNames(widgetElement, theme, true, isOnLeftSide);
}

function handleSwipeGesture(
  event: {
    target: HTMLDivElement;
    duration: number;
    x0: number;
    y0: number;
    swipe: {
      angle: number;
      down: boolean;
      left: boolean;
      right: boolean;
      speed: number;
      up: boolean;
      velocity: {
        x: number;
        y: number;
      };
    };
  },
  theme: string | undefined,
  x: number
): void {
  if (!event || !event.swipe) return;
  const vw = right();
  const cw = event.target.clientWidth;
  const isOnLeftSide = x < (vw - edgetOffset) / 2;
  const isCollapsed = event.target.classList.contains(
    "tipLinkWidget_collapsed"
  );
  console.log({
    vw,
    cw,
    swipeRight: event.swipe.right,
    swipeLeft: event.swipe.left,
    x0: event.x0,
    y0: event.y0,
    isOnLeftSide,
  });
  if (isOnLeftSide && !isCollapsed && event.swipe.left) {
    showCollapsedWalletWidget(event.target, theme, true);
  } else if (isOnLeftSide && isCollapsed && event.swipe.right) {
    showExpandedWalletWidget(event.target, theme);
  } else if (!isOnLeftSide && !isCollapsed && event.swipe.right) {
    showCollapsedWalletWidget(event.target, theme, false);
  } else if (!isOnLeftSide && isCollapsed && event.swipe.left) {
    showExpandedWalletWidget(event.target, theme);
  }
}

const windowResizeListener = () => {
  const target = document.getElementById("tiplink-widget-draggable");
  if (!target) {
    return;
  }
  const dataXAttr = target.getAttribute("data-x");
  const dataYAttr = target.getAttribute("data-y");
  const parsedX = dataXAttr ? parseFloat(dataXAttr) : 0;
  const parsedY = dataYAttr ? parseFloat(dataYAttr) : 0;
  const { x, y } = stickToNearestSideEdge(
    parsedX,
    parsedY,
    target as HTMLDivElement
  );

  // Update transform and attributes
  target.style.transform = `translate(${x}px, ${y}px)`;
  target.setAttribute("data-x", x + "");
  target.setAttribute("data-y", y + "");
};

function setupTouchIntercept() {
  document.body.addEventListener("touchmove", preventDefaultScroll, {
    passive: false,
  });
  document.body.style.touchAction = "none";
}

function teardownTouchIntercept() {
  document.body.removeEventListener("touchmove", preventDefaultScroll);
  document.body.style.touchAction = "";
}

function setupWalletWidgetClassNames(
  theme?: string,
  isCollapsed?: boolean,
  isLeftSide?: boolean,
  isOnMount?: boolean
) {
  const classNames = [];

  if (isCollapsed) {
    classNames.push(
      "tipLinkWidget_collapsed",
      isLeftSide
        ? "tipLinkWidget_collapsed_left"
        : "tipLinkWidget_collapsed_right"
    );
  } else {
    classNames.push("tipLinkWidget_expanded");
  }

  if (isOnMount) {
    classNames.push("tipLinkWidget_enter");
  }

  switch (theme) {
    case "dark":
      classNames.push("tipLinkWidget_dark");
      break;
    case "light":
      classNames.push("tipLinkWidget_light");
      break;
    case "system":
    default:
      classNames.push("tiplinkWidget_system");
  }
  return classNames.join(" ");
}

function updateWalletWidgetClassNames(
  widgetElement: HTMLDivElement,
  theme?: string,
  isCollapsed?: boolean,
  isOnLeftSide?: boolean
) {
  const className = setupWalletWidgetClassNames(
    theme,
    isCollapsed,
    isOnLeftSide
  );
  widgetElement.setAttribute("class", className);
}

